entry.content:
neblla_create_product: inputSchema  parameters: +input.maxAmount input.maxAmount description: donation: the largest, in cents (default 50000) +input.minAmount input.minAmount description: donation: the smallest amount the giver may choose, in cents +input.presetAmount input.presetAmount description: donation: the amount Stripe's page offers first, in cents -"subscription"] +"subscription", "donation"]
neblla_update_app_payments: description, inputSchema  -checkout and +checkout, -product. +product and the «firma» (Neblla's logo and the coffee cup, donations).  parameters: +input.signature input.signature description: The «firma»: { enabled, position?, amountPreset?, thankYou? }
neblla_update_product: inputSchema  parameters: +input.maxAmount input.maxAmount description: donation: the largest, in cents +input.minAmount input.minAmount description: donation: the smallest amount the giver may choose, in cents +input.presetAmount input.presetAmount description: donation: the amount offered first, in cents
